/**
 * Development-only, off by default: answers the isolated-workspace commands of
 * the `compare-code` preview room so its "Apply to my folder" review shows a
 * realistic multi-file patch -- a modified file with two hunks, a new file, a
 * deleted one, a rename, a binary image and a 1,200-line generated file.
 *
 *   ?preview&applyseed            applies cleanly
 *   ?preview&applyseed=conflict   one file conflicts, one has uncommitted edits
 */
import { answer } from './previewTauri'

const MODIFIED = `diff --git a/src/radar/retry.test.ts b/src/radar/retry.test.ts
index 3f2a1c4..9b07d1e 100644
--- a/src/radar/retry.test.ts
+++ b/src/radar/retry.test.ts
@@ -1,6 +1,6 @@
-import { describe, expect, it } from 'vitest'
+import { describe, expect, it, vi } from 'vitest'
 import { retry } from './retry'
 import { fetchFrame, frame } from './fixtures'

 describe('retry', () => {
   it('gives up after three tries', async () => {
@@ -18,8 +18,10 @@ describe('retry', () => {
   it('waits between tries', async () => {
     let calls = 0
     const flaky = () => (++calls < 3 ? Promise.reject(new Error('busy')) : fetchFrame())
-    await sleep(100)
-    expect(calls).toBe(3)
+    vi.useFakeTimers()
+    const done = retry(flaky)
+    await vi.runAllTimersAsync()
+    expect(await done).toBe(frame)
+    vi.useRealTimers()
   })
 })
`
const ADDED = `diff --git a/src/radar/jitter.ts b/src/radar/jitter.ts
new file mode 100644
index 0000000..5d1e0a2
--- /dev/null
+++ b/src/radar/jitter.ts
@@ -0,0 +1,7 @@
+/** Random spread added to each retry delay, so clients do not retry in step. */
+export const RETRY_JITTER_MS = 50
+
+export function withJitter(ms: number, random = Math.random): number {
+  return ms + Math.round(random() * RETRY_JITTER_MS)
+}
+export default withJitter
\\ No newline at end of file
`
const DELETED = `diff --git a/src/radar/sleep.ts b/src/radar/sleep.ts
deleted file mode 100644
index 7c4b2e9..0000000
--- a/src/radar/sleep.ts
+++ /dev/null
@@ -1,3 +0,0 @@
-export function sleep(ms: number): Promise<void> {
-  return new Promise((resolve) => setTimeout(resolve, ms))
-}
`
const RENAMED = `diff --git a/src/radar/backoff.ts b/src/radar/delay.ts
similarity index 86%
rename from src/radar/backoff.ts
rename to src/radar/delay.ts
index 1a2b3c4..4c3b2a1 100644
--- a/src/radar/backoff.ts
+++ b/src/radar/delay.ts
@@ -1,4 +1,4 @@
-export function backoff(attempt: number): number {
+export function delay(attempt: number): number {
   // 100, 200, 400 ... capped at two seconds.
   return Math.min(100 * 2 ** attempt, 2_000)
 }
`
const BINARY = `diff --git a/docs/radar-retry.png b/docs/radar-retry.png
new file mode 100644
index 0000000000000000000000000000000000000000..e69de29bb2d1d6434b8b29ae775ad8c2e48c5391
GIT binary patch
literal 68
zcmeAS@N?(olHy0uVBq!ia0vp^j6lr8!2~2fd3HJjDVB6cUq=Rpjs4tz5?O(Kg=CK)
Uj~LMoUq=Rpjs4tz5?O(K0J4aDuK)l5

literal 0
HcmV?d00001

`
const LONG = (() => {
  const rows = Array.from(
    { length: 1200 },
    (_, i) => `+  { station: 'KX${String(i).padStart(4, '0')}', lat: ${(30 + (i % 90) / 7).toFixed(3)}, lon: ${(-120 + (i % 60) / 3).toFixed(3)}, elevationM: ${100 + ((i * 37) % 2400)} },`
  )
  return `diff --git a/src/radar/stations.generated.ts b/src/radar/stations.generated.ts
index 0000001..0000002 100644
--- a/src/radar/stations.generated.ts
+++ b/src/radar/stations.generated.ts
@@ -1,3 +1,1202 @@
 // Generated by scripts/stations.mjs. Do not edit.
 export const STATIONS = [
+${rows.join('\n').slice(1)}
 ]
`
})()

const PATCH = MODIFIED + ADDED + DELETED + RENAMED + BINARY + LONG
const TARGET = 'C:\\Users\\me\\projects\\acme-weather'

export function seedApplyReviewPreview(mode: string | null) {
  if (mode === null) return
  const conflict = mode === 'conflict'
  answer('room_workspace_patch', () => PATCH)
  answer('room_workspace_apply_preview', () => ({
    patch: PATCH,
    target: TARGET,
    clean: !conflict,
    files: conflict
      ? [
          { path: 'src/radar/retry.test.ts', ok: true },
          { path: 'src/radar/jitter.ts', ok: true },
          {
            path: 'src/radar/sleep.ts',
            ok: false,
            reason: 'error: src/radar/sleep.ts: does not exist in index',
          },
          { path: 'src/radar/delay.ts', ok: true },
          { path: 'docs/radar-retry.png', ok: true },
          { path: 'src/radar/stations.generated.ts', ok: true },
        ]
      : [],
    dirty: conflict ? ['src/radar/retry.test.ts'] : [],
  }))
  answer('room_workspace_apply', (a) => (Array.isArray(a.paths) ? a.paths.length : 6))
  answer('room_workspace_undo_apply', () => null)
}
